#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long num = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long den = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (den == 0) {
        puts("ERROR");
        return 0;
    }
    // Compute continued fraction terms
    long terms[200];
    int count = 0;
    while (den != 0) {
        // floor division handling negative numbers correctly
        long a = num / den;
        long r = num % den;
        // Adjust for floor division (C truncates toward 0)
        if (r != 0 && ((r < 0) != (den < 0))) {
            a -= 1;
            r += den;
        }
        if (llabs((long long)a) > 100000) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        if (count >= 200) break; // safety
        terms[count++] = a;
        num = den;
        den = r;
    }
    // Output in [a0; a1, a2, ...] format
    printf("[");
    for (int i = 0; i < count; ++i) {
        if (i == 0) {
            printf("%ld", terms[i]);
            if (count > 1) printf("; ");
        } else {
            printf("%ld", terms[i]);
            if (i != count - 1) printf(", ");
        }
    }
    puts("]");
    return 0;
}
